use serde_json::Value;
use std::collections::HashMap;

pub fn solve(input: Value) -> Value {
    let mut map = HashMap::new();

    for item in input.as_array().unwrap() {
        let key = item.as_array().unwrap()[0].as_i64().unwrap();
        let value = item.as_array().unwrap()[1].as_i64().unwrap();
        let sum = map.entry(key).or_insert(0);
        *sum += value;
    }

    let mut result = map.into_iter().map(|(k, v)| {
        let mut arr = [Value::Number(Value::from_i64(k).unwrap()), Value::Number(Value::from_i64(v).unwrap())];
        arr.into()
    }).collect::<Vec<Value>>();

    result.sort_by(|a, b| {
        let a0 = a[0].as_i64().unwrap();
        let b0 = b[0].as_i64().unwrap();
        a0.cmp(&b0)
    });

    Value::Array(result)
}
